export function initModels(sequelize: Sequelize) {
  initDailyRevenue(sequelize)
  initAnalyticsEvent(sequelize)
  initMixedCaseTable(sequelize)
  initAuditLog(sequelize)
  initCategory(sequelize)
  initCustomerProfile(sequelize)
  initCustomer(sequelize)
  initEvent(sequelize)
  initMeasurement(sequelize)
  initMessage(sequelize)
  initOrderItem(sequelize)
  initOrder(sequelize)
  initProduct(sequelize)
  initShipment(sequelize)
  initTypeSample(sequelize)

  AnalyticsEvent.belongsTo(Customer, { as: "customer", foreignKey: "customer_id", targetKey: "id", onDelete: "SET NULL", onUpdate: "NO ACTION" })
  Customer.hasMany(AnalyticsEvent, { as: "events", foreignKey: "customer_id", sourceKey: "id" })
  Category.belongsTo(Category, { as: "parent", foreignKey: "parent_id", targetKey: "id", onDelete: "NO ACTION", onUpdate: "NO ACTION" })
  Category.hasMany(Category, { as: "categories", foreignKey: "parent_id", sourceKey: "id" })
  CustomerProfile.belongsTo(Customer, { as: "customer", foreignKey: "customer_id", targetKey: "id", onDelete: "CASCADE", onUpdate: "NO ACTION" })
  Customer.hasOne(CustomerProfile, { as: "customer_profile", foreignKey: "customer_id", sourceKey: "id" })
  Message.belongsTo(Customer, { as: "recipient", foreignKey: "recipient_id", targetKey: "id", onDelete: "SET NULL", onUpdate: "NO ACTION" })
  Customer.hasMany(Message, { as: "messages_recipient_id", foreignKey: "recipient_id", sourceKey: "id" })
  Message.belongsTo(Customer, { as: "sender", foreignKey: "sender_id", targetKey: "id", onDelete: "CASCADE", onUpdate: "NO ACTION" })
  Customer.hasMany(Message, { as: "messages_sender_id", foreignKey: "sender_id", sourceKey: "id" })
  OrderItem.belongsTo(Order, { as: "order", foreignKey: "order_id", targetKey: "id", onDelete: "CASCADE", onUpdate: "NO ACTION" })
  Order.hasMany(OrderItem, { as: "order_items", foreignKey: "order_id", sourceKey: "id" })
  OrderItem.belongsTo(Product, { as: "product", foreignKey: "product_id", targetKey: "id", onDelete: "NO ACTION", onUpdate: "NO ACTION" })
  Product.hasMany(OrderItem, { as: "order_items", foreignKey: "product_id", sourceKey: "id" })
  Order.belongsTo(Customer, { as: "customer", foreignKey: "customer_id", targetKey: "id", onDelete: "CASCADE", onUpdate: "NO ACTION" })
  Customer.hasMany(Order, { as: "orders", foreignKey: "customer_id", sourceKey: "id" })
  Product.belongsTo(Category, { as: "category", foreignKey: "category_id", targetKey: "id", onDelete: "NO ACTION", onUpdate: "NO ACTION" })
  Category.hasMany(Product, { as: "products", foreignKey: "category_id", sourceKey: "id" })
  Shipment.belongsTo(Category, { as: "category", foreignKey: "category_slug", targetKey: "slug", onDelete: "NO ACTION", onUpdate: "NO ACTION" })
  Category.hasMany(Shipment, { as: "shipments", foreignKey: "category_slug", sourceKey: "slug" })

  return { DailyRevenue, AnalyticsEvent, MixedCaseTable, AuditLog, Category, CustomerProfile, Customer, Event, Measurement, Message, OrderItem, Order, Product, Shipment, TypeSample }
}
